type CapturedHandler = (...args: unknown[]) => unknown;

interface CapturedExtension {
	tools: Map<string, ToolDefinition>;
	handlers: Map<string, CapturedHandler[]>;
	getActiveTools(): string[];
	messages: CapturedMessage[];
}

interface CapturedMessageOptions {
	triggerTurn?: boolean;
	deliverAs?: "steer" | "followUp" | "nextTurn";
}

interface CapturedMessage {
	customType: string;
	content?: unknown;
	display?: boolean;
	details?: unknown;
	options?: CapturedMessageOptions;
}

function readFixture(name: string): unknown {
	const relativePath = fixturePaths[name] ?? name;
	return JSON.parse(readFileSync(join(fixturesDir, relativePath), "utf-8"));
}

function loadExperimentExtension(): CapturedExtension {
	const tools = new Map<string, ToolDefinition>();
	const handlers = new Map<string, CapturedHandler[]>();
	let activeTools = ["read", "write"];
	const messages: CapturedMessage[] = [];
	const api = {
		registerTool(tool: ToolDefinition) {
			tools.set(tool.name, tool);
		},
		on(event: string, handler: CapturedHandler) {
			const existing = handlers.get(event) ?? [];
			existing.push(handler);
			handlers.set(event, existing);
		},
		getActiveTools() {
			return activeTools;
		},
		setActiveTools(toolNames: string[]) {
			activeTools = toolNames;
		},
		sendMessage(message: CapturedMessage, options?: CapturedMessageOptions) {
			messages.push({ ...message, options });
		},
	} as unknown as ExtensionAPI;

	experimentResearchExtension(api);
	return { tools, handlers, getActiveTools: () => activeTools, messages };
}

function asRecord(value: unknown): Record<string, unknown> {
	expect(typeof value).toBe("object");
	expect(value).not.toBeNull();
	return value as Record<string, unknown>;
}

function asString(value: unknown): string {
	if (typeof value !== "string") {
		throw new Error(`Expected string, got ${typeof value}`);
	}
	return value;
}

async function withTempCwd<T>(fn: (cwd: string) => Promise<T>): Promise<T> {
	const cwd = mkdtempSync(join(tmpdir(), "pi-exp-test-"));
	try {
		return await fn(cwd);
	} finally {
		rmSync(cwd, { recursive: true, force: true });
	}
}

