export function successActionResult(
	summary: string,
	payload: Record<string, unknown> = {},
	artifacts: Static<typeof ArtifactRefSchema>[] = [],
): ActionResult {
	return {
		status: "success",
		artifacts,
		retrySafe: false,
		needsOperator: false,
		safeToResume: true,
		summary,
		payload,
	};
}

